import { createServer } from 'node:http';
import sharp from 'sharp';
import { Engine } from '../../src/core.js';
import { BrowserAdapter } from '../../src/browser.js';
import { parsePolicy, assertUrlAllowed } from '../../src/policy.js';
// Real VP8-encoded2s motion clip generated from ffmpeg testsrc2 (160x90,10fps).
// Kept inline so acceptance has no ffmpeg/runtime/download prerequisite.
const motion = Buffer.from(
  '',
  'base64',
);
const html =
  "<!doctype html><meta charset=\"utf-8\"><style>body{margin:0;background:#eee}#board{position:absolute;left:10px;top:10px;width:600px;height:250px;touch-action:none}#video{position:absolute;left:10px;top:280px;width:160px;height:90px}#status{position:absolute;left:10px;top:390px}#unsafe{position:absolute;left:650px;top:10px}</style>\n<canvas id=\"board\" width=\"600\" height=\"250\"></canvas><video id=\"video\" src=\"/motion.webm\" width=\"160\" height=\"90\" autoplay muted loop playsinline></video><div role=\"status\" id=\"status\">Ready</div><div role=\"status\" id=\"video-ready\" style=\"position:absolute;left:10px;top:420px\">Video waiting</div><button id=\"change\" type=\"button\" style=\"position:absolute;left:700px;top:200px\" onclick=\"document.getElementById('status').textContent='Revision changed'\">Change revision</button><input id=\"unsafe\" aria-label=\"Password\" value=\"CANARY_SECRET\"><script>\nconst board=document.getElementById('board'),ctx=board.getContext('2d'),status=document.getElementById('status');let x=20,y=20,mouse=false,touch=false,trusted=true,pointerType='',startX=0;\nfunction paint(){ctx.fillStyle='white';ctx.fillRect(0,0,600,250);ctx.fillStyle='#f00';ctx.fillRect(x,y,40,40);ctx.fillStyle='#00f';ctx.fillRect(450,150,100,80)}paint();\nboard.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')return;mouse=true;trusted&&=e.isTrusted;pointerType=e.pointerType;});\nboard.addEventListener('pointermove',e=>{if(!mouse||e.pointerType!=='mouse')return;trusted&&=e.isTrusted;x=e.clientX-30;y=e.clientY-30;paint();});\nboard.addEventListener('pointerup',e=>{if(!mouse||e.pointerType!=='mouse')return;mouse=false;trusted&&=e.isTrusted;status.textContent=`Drag ended x=${Math.round(x)} y=${Math.round(y)} trusted=${trusted} pointer=${pointerType}`;});\nboard.addEventListener('pointercancel',()=>{mouse=false;});\nboard.addEventListener('touchstart',e=>{touch=true;trusted&&=e.isTrusted;startX=e.touches[0].clientX;e.preventDefault();},{passive:false});\nboard.addEventListener('touchmove',e=>{if(!touch)return;trusted&&=e.isTrusted;x=20+e.touches[0].clientX-startX;paint();e.preventDefault();},{passive:false});\nboard.addEventListener('touchend',e=>{if(!touch)return;touch=false;trusted&&=e.isTrusted;status.textContent=`Swipe ended x=${Math.round(x)} trusted=${trusted} touch=${e instanceof TouchEvent}`;e.preventDefault();},{passive:false});\nboard.addEventListener('touchcancel',e=>{touch=false;status.textContent='Touch cancelled';e.preventDefault();},{passive:false});\ndocument.getElementById('video').addEventListener('playing',()=>{document.getElementById('video-ready').textContent='Video playing'});</script>";
export async function visualFeatureServer(gestures = true) {
  const http = createServer((q, r) => {
    r.setHeader('cache-control', 'no-store');
    r.setHeader('content-type', q.url === '/motion.webm' ? 'video/webm' : 'text/html');
    r.end(q.url === '/motion.webm' ? motion : html);
  });
  await new Promise<void>(r => http.listen(0, '127.0.0.1', r));
  const origin = `http://127.0.0.1:${(http.address() as { port: number }).port}`;
  const policyInput = {
    allowedOrigins: [origin],
    allowLoopback: true,
    actionTimeoutMs: 10000,
    browserTargets: [
      {
        id: 'motion',
        label: 'Motion fixture',
        url: origin,
        classification: 'PUBLIC',
        visual: { enabled: true, maskSelectors: [] },
        gestures: { enabled: gestures, surfaces: [{ id: 'board', selector: '#board', kinds: ['drag', 'swipe'] }] },
        controls: [{ selector: '#change', actions: ['click'] }],
      },
    ],
  };
  return { origin, policyInput, close: () => new Promise<void>(r => http.close(() => r())) };
}
export async function visualFeatureEngine(gestures = true) {
  const fixture = await visualFeatureServer(gestures);
  const policy = parsePolicy(fixture.policyInput);
  const engine = new Engine(policy, { browser: new BrowserAdapter(policy, u => assertUrlAllowed(u, policy)) });
  try {
    const target = (await engine.listTargets()).targets[0]!;
    const session = await engine.open(target.target_id);
    await engine.wait(session.session_id, { role: 'status', name: 'Video playing' }, 5000);
    return {
      ...fixture,
      engine,
      target,
      session,
      close: async () => {
        await engine.shutdown();
        await fixture.close();
      },
    };
  } catch (error) {
    await engine.shutdown();
    await fixture.close();
    throw error;
  }
}
export async function pixel(png: Buffer, x: number, y: number) {
  const { data, info } = await sharp(png).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  return [...data.subarray((y * info.width + x) * info.channels, (y * info.width + x) * info.channels + 3)];
}
